from strands import Agent, tool
from strands.models import BedrockModel

# Real tool implementations -- plain functions, not registered with the agent directly.
def search_orders(order_id: str = "", status: str = "") -> str:
    """Search orders by id, date, or status."""
    return f"Searched orders: order_id={order_id!r} status={status!r}"

def issue_refund(order_id: str, amount: float) -> str:
    """Issue a refund for an order."""
    return f"Refunded {amount} for order {order_id}"

# ... rest of your real tool functions, undecorated

ALL_TOOLS = {"search_orders": search_orders, "issue_refund": issue_refund}

@tool
def list_available_tools() -> list:
    """Return a catalog of available tool names with one-line summaries.
    Call call_tool(name, arguments) to invoke one."""
    return [{"name": name, "summary": fn.__doc__} for name, fn in ALL_TOOLS.items()]

@tool
def call_tool(name: str, arguments: dict) -> str:
    """Invoke a named tool from the catalog with the given keyword arguments."""
    if name not in ALL_TOOLS:
        return f"Unknown tool: {name}. Call list_available_tools() first."
    return ALL_TOOLS[name](**arguments)

# The agent only ever sees these two small, fixed meta-tool schemas.
agent = Agent(
    model=BedrockModel(model_id="us.anthropic.claude-sonnet-5"),
    tools=[list_available_tools, call_tool],
)
